private void cloud(Bundle args){
  SharedPreferences prefs=PreferenceManager.getDefaultSharedPreferences(getContext());
  new SimpleTask<Void>(){
    @Override protected void onPreExecute(Bundle args){
      Helper.setViewsEnabled(cardCloud,false);
    }
    @Override protected void onPostExecute(Bundle args){
      Helper.setViewsEnabled(cardCloud,true);
    }
    @Override protected Void onExecute(Context context, Bundle args) throws Throwable {
      String command=args.getString("command");
      CloudSync.execute(context,command,true);
      return null;
    }
    @Override protected void onExecuted(Bundle args, Void data){
      String command=args.getString("command");
      if ("logout".equals(command)) prefs.edit().remove("cloud_user").remove("cloud_password").apply();
      if ("login".equals(command) || "logout".equals(command)) WorkerSync.init(getContext());
      view.post(new Runnable(){
        @Override public void run(){
          view.scrollTo(0,cardCloud.getTop());
        }
      });
    }
    @Override protected void onException(Bundle args, Throwable ex){
      if (ex instanceof SecurityException) {
        prefs.edit().remove("cloud_user").remove("cloud_password").apply();
        AlertDialog.Builder builder=new AlertDialog.Builder(getContext()).setIcon(R.drawable.twotone_warning_24).setTitle(getString(R.string.title_advanced_cloud_invalid)).setNegativeButton(android.R.string.cancel,null);
        String message=ex.getMessage();
        if (!TextUtils.isEmpty(message)) builder.setMessage(message);
        builder.show();
      } else Log.unexpectedError(getParentFragmentManager(),ex);
    }
  }.execute(FragmentOptionsBackup.this,args,"cloud");
}
